css:
/* Counter-Strike 1.6: VGUI olive chrome + pixel-art battlefield */
*, *::before, *::after { border-radius: 0 !important; }
body, .chat-markdown, .composer-tiptap, [data-slot="button"], [data-slot="input"] {
  font-family: Tahoma, Verdana, "DejaVu Sans", "Bitstream Vera Sans", sans-serif;
}

/* ---- Chat area: poster stripes, T vs CT, HUD ---- */
[data-workspace-area="conversation"] {
  background-color: #1f2133 !important;
  background-image: linear-gradient(to right, #3a3d50 0 16.6%, #303347 16.6% 33.3%, #282a40 33.3% 50%, #22223f 50% 66.6%, #1f1b45 66.6% 83.3%, #19134a 83.3%) !important;
  background-size: 100% 100% !important;
  cursor: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABcAAAAXAgMAAACdRDwzAAAACVBMVEUAAAAKOgoy/zLayBfpAAAAA3RSTlMA//9EUNYhAAAAPElEQVR42mNgYGBkYGBgYmBgdWBgYGJgYGDATzFANKACRlH7NQyhv1lC7dcwhv5ifvD1GgPDFUxV5FgEANkrCQ6GaubPAAAAAElFTkSuQmCC") 11 11, crosshair;
  image-rendering: pixelated;
}
[data-workspace-area="conversation"] * { image-rendering: auto; }
@media (min-width: 1100px) {
  [data-workspace-area="conversation"] {
    background-image:
      url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAEAAAAAHAQMAAACC+tlJAAAABlBMVEUAAAD/oAC1+DHLAAAAAnRSTlMA/1uRIrUAAAA7SURBVHjaYyjg+f2Av+H8PhYGgQetDIz/fjB1fGBgYPjPwMDEAAVMDAwMDD8aGBiYKuAiQgoNvxmVOABAOQ4tL6a4HwAAAABJRU5ErkJggg=="),
      url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACYAAAAHAQMAAABeA61+AAAABlBMVEUAAAD/oAC1+DHLAAAAAnRSTlMA/1uRIrUAAAAvSURBVHjaY/j9QMHuB4uCK8OPB0wMDAwMDEwJDAwcDEwLGBhOMEBEGH4/ULD7AQDvNgp8raCQkwAAAABJRU5ErkJggg=="),
      linear-gradient(to right, #3a3d50 0 16.6%, #303347 16.6% 33.3%, #282a40 33.3% 50%, #22223f 50% 66.6%, #1f1b45 66.6% 83.3%, #19134a 83.3%) !important;
    background-repeat: no-repeat !important;
    background-size: 192px 21px, 114px 21px, 100% 100% !important;
    background-position: left 20px bottom 18px, right 20px bottom 18px, 0 0 !important;
  }
}
@media (min-width: 1500px) {
  [data-workspace-area="conversation"] {
    background-image:
      url("data:image/png;base64,"),
      url("data:image/png;base64,"),
      url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAEAAAAAHAQMAAACC+tlJAAAABlBMVEUAAAD/oAC1+DHLAAAAAnRSTlMA/1uRIrUAAAA7SURBVHjaYyjg+f2Av+H8PhYGgQetDIz/fjB1fGBgYPjPwMDEAAVMDAwMDD8aGBiYKuAiQgoNvxmVOABAOQ4tL6a4HwAAAABJRU5ErkJggg=="),
      url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACYAAAAHAQMAAABeA61+AAAABlBMVEUAAAD/oAC1+DHLAAAAAnRSTlMA/1uRIrUAAAAvSURBVHjaY/j9QMHuB4uCK8OPB0wMDAwMDEwJDAwcDEwLGBhOMEBEGH4/ULD7AQDvNgp8raCQkwAAAABJRU5ErkJggg=="),
      linear-gradient(to right, #3a3d50 0 16.6%, #303347 16.6% 33.3%, #282a40 33.3% 50%, #22223f 50% 66.6%, #1f1b45 66.6% 83.3%, #19134a 83.3%) !important;
    background-repeat: no-repeat !important;
    background-size: 180px 180px, 180px 180px, 192px 21px, 114px 21px, 100% 100% !important;
    background-position: left 0 bottom 52px, right 0 bottom 52px, left 20px bottom 18px, right 20px bottom 18px, 0 0 !important;
  }
}
.messages-timeline-scroll, [data-chat-composer-form] { background: transparent !important; }
.composer-tiptap, [data-slot="composer-host"] [contenteditable] { cursor: text; }

/* In-game text panel behind assistant replies */
.dark [data-message-role="assistant"] .chat-markdown {
  background: rgba(10,10,20,.62) !important;
  border: 1px solid rgba(0,0,0,.6);
  padding: 10px 14px !important;
}
.chat-markdown-codeblock { border: 1px solid #000 !important; box-shadow: 2px 2px 0 rgba(0,0,0,.4) !important; }

/* ---- Sidebar: VGUI panel ---- */
[data-slot="sidebar-inner"] {
  background-color: #3e4637 !important;
  background-image:
    linear-gradient(to top, #b39a64 0 10px, #8c7646 10px 12px, transparent 12px),
    linear-gradient(to right, rgba(255,255,255,.04) 1px, transparent 1px) !important;
  background-repeat: no-repeat, repeat !important;
  background-size: 100% 100%, 4px 4px !important;
  background-position: 0 0, 0 0 !important;
  image-rendering: pixelated;
  border-right: 1px solid #292c21 !important;
  box-shadow: inset 1px 1px 0 #6f7a64;
}
[data-slot="sidebar-inner"] * { image-rendering: auto; }
[data-thread-item] { border: 1px solid transparent; text-shadow: 1px 1px 0 rgba(0,0,0,.55); }
[data-thread-item]:hover { border-color: #8c9284 #292c21 #292c21 #8c9284; }
[data-slot="sidebar-inner"] [data-slot="input"] { background: #2f3529 !important; }

/* Title bar like a VGUI frame */
[data-chat-header] {
  background: #4c5844 !important;
  border-bottom: 1px solid #292c21 !important;
  box-shadow: inset 0 1px 0 #8c9284;
}

/* VGUI bevels */
[data-slot="button"] {
  border: 1px solid !important;
  border-color: #8c9284 #292c21 #292c21 #8c9284 !important;
  box-shadow: none !important;
  transition: none !important;
}
[data-slot="button"]:hover { filter: brightness(1.12); }
[data-slot="button"]:active { border-color: #292c21 #8c9284 #8c9284 #292c21 !important; }
[data-slot="input"], [data-slot="select-trigger"] {
  border: 1px solid !important;
  border-color: #292c21 #8c9284 #8c9284 #292c21 !important;
  box-shadow: none !important;
}
[data-slot="composer-host"], [data-slot="composer-host"]:focus-within {
  background: #3e4637 !important;
  border: 1px solid !important;
  border-color: #8c9284 #292c21 #292c21 #8c9284 !important;
  box-shadow: 3px 3px 0 rgba(0,0,0,.4) !important;
}
.composer-tiptap, .composer-tiptap:focus, .composer-tiptap:focus-visible, [data-slot="composer-host"] [contenteditable]:focus { outline: none !important; box-shadow: none !important; }
[data-user-message-bubble] {
  border: 1px solid !important;
  border-color: #8c9284 #292c21 #292c21 #8c9284 !important;
  box-shadow: 2px 2px 0 rgba(0,0,0,.35) !important;
}
[data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-thread-details-card] {
  border: 1px solid !important;
  border-color: #8c9284 #292c21 #292c21 #8c9284 !important;
  box-shadow: 4px 4px 0 rgba(0,0,0,.45) !important;
}
[data-slot="tooltip-popup"] {
  background: #4c5844 !important; color: #dedfd6 !important;
  border: 1px solid #292c21 !important; box-shadow: none !important;
}
svg.lucide { stroke-linecap: square; stroke-linejoin: miter; }

/* VGUI scrollbars */
::-webkit-scrollbar { width: 12px; height: 12px; }
::-webkit-scrollbar-track { background: #2f3529; }
::-webkit-scrollbar-thumb { background: #4c5844; border: 1px solid; border-color: #8c9284 #292c21 #292c21 #8c9284; }
[data-slot="scroll-area-thumb"] { background: #5a6750 !important; border: 1px solid #292c21; }

/* ---- Settings: the in-game Options dialog ---- */
[data-settings-page-scroll] {
  --contrast-foreground: #dedfd6; --contrast-muted-foreground: #a0aa95;
  --contrast-border: #292c21; --contrast-input: #3e4637; --card: #4c5844;
  --background: #3e4637; --contrast-placeholder: #8a9280; --contrast-icon-muted: #a0aa95;
  background: #4c5844 !important;
  box-shadow: inset 1px 1px 0 #8c9284;
  color: #dedfd6;
}
div:has(> header + div [data-settings-page-scroll]) { background: #4c5844 !important; }
header:has(+ div [data-settings-page-scroll]) {
  background: #4c5844 !important;
  border-bottom: 1px solid #292c21 !important;
  box-shadow: inset 0 1px 0 #8c9284, 0 1px 0 #6f7a64;
  position: relative; z-index: 1;
}
[data-settings-page-scroll] h2 { color: #c4b550 !important; font-weight: 400 !important; }
[data-settings-page-scroll] h3 { font-weight: 400 !important; }
[data-slot="settings-group"] {
  background: transparent !important;
  border: 1px solid #292c21 !important;
  box-shadow: 1px 1px 0 #6f7a64, inset 1px 1px 0 #6f7a64 !important;
}
[data-slot="settings-group"] > * + * { border-top: 1px solid #292c21 !important; box-shadow: inset 0 1px 0 #6f7a64; }
[data-slot="settings-row"]:has([data-slot="switch"][data-checked]) h3 { color: #c4b550 !important; }
[data-settings-page-scroll] [data-slot="select-trigger"], [data-settings-page-scroll] [data-slot="input"], [data-settings-page-scroll] [data-slot="textarea"] {
  background: #3e4637 !important; color: #dedfd6 !important;
}
[data-settings-page-scroll] [data-slot="button"] { background-color: #4c5844 !important; color: #dedfd6 !important; }

/* Switches become VGUI checkboxes */
[data-slot="switch"], [data-slot="checkbox"], [data-slot="radio"] {
  width: 15px !important; height: 15px !important; padding: 0 !important;
  display: inline-flex !important; align-items: center; justify-content: center;
  background: #3e4637 !important;
  border: 1px solid !important; border-color: #292c21 #8c9284 #8c9284 #292c21 !important;
  box-shadow: none !important; color: #f0f0e6 !important;
}
[data-slot="switch-thumb"] {
  width: 5px !important; height: 9px !important; margin: -2px 0 0 !important;
  background: transparent !important; box-shadow: none !important;
  border: solid #f0f0e6; border-width: 0 2px 2px 0;
  translate: none !important; scale: none !important; transform: rotate(45deg) !important;
  transition: none !important;
}
[data-slot="switch"][data-unchecked] [data-slot="switch-thumb"] { opacity: 0; }
[data-slot="switch"][data-mixed] [data-slot="switch-thumb"] { width: 7px !important; height: 0 !important; margin: 0 !important; border-width: 0 0 2px; transform: none !important; opacity: 1; }

/* Tabs and pressed toggles */
[data-slot="toggle"] {
  border: 1px solid !important; border-color: #8c9284 #292c21 #292c21 #8c9284 !important;
  background: #4c5844 !important; color: #dedfd6 !important;
}
[data-slot="toggle"][data-pressed] { border-color: #292c21 #8c9284 #8c9284 #292c21 !important; background: #3e4637 !important; color: #c4b550 !important; }
[data-slot="sidebar-menu-button"][data-active="true"] {
  color: #c4b550 !important; background: #4c5844 !important;
  box-shadow: inset 1px 1px 0 #8c9284, inset -1px -1px 0 #292c21 !important;
}

/* Dropdowns */
[data-slot="select-popup"] {
  --contrast-foreground: #dedfd6; --contrast-muted-foreground: #a0aa95;
  background: #3e4637 !important; color: #dedfd6;
  border: 1px solid !important; border-color: #8c9284 #292c21 #292c21 #8c9284 !important;
  box-shadow: 3px 3px 0 rgba(0,0,0,.45) !important;
}
[data-slot="select-item"][data-highlighted], [data-slot="menu-item"][data-highlighted] { background: #958831 !important; color: #fff !important; }

/* Light mode: de_dust daylight */
:root:not(.dark) [data-workspace-area="conversation"] { background-color: #e6d6ac !important; background-image: linear-gradient(to right, #ecdcb2 0 16.6%, #e6d5a9 16.6% 33.3%, #e0cea0 33.3% 50%, #dac797 50% 66.6%, #d4c08e 66.6% 83.3%, #cdb985 83.3%) !important; background-size: 100% 100% !important; }
:root:not(.dark) [data-message-role="assistant"] .chat-markdown { background: rgba(255,250,235,.7) !important; padding: 10px 14px !important; }
